@push('scripts')
<script>
$(function(){
 const table=$('#gsnTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.goods-sent-notes.dt')),data:d=>{d.from_date=$('#gsnFrom').val();d.to_date=$('#gsnTo').val()}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-nowrap'},{data:'mo',orderable:false,searchable:false},{data:'number',name:'number'},{data:'contract_number',name:'contract_number',defaultContent:'—'},{data:'date',name:'sent_date',render:d=>d?new Date(d+'T00:00:00').toLocaleDateString():''},{data:'order_date',orderable:false,searchable:false},{data:'vehicle_number',name:'vehicle_number',defaultContent:'—'},{data:'user_input',orderable:false,searchable:false}],order:[[5,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 $('#gsnFilter').on('click',()=>table.ajax.reload());$('#gsnExport').on('click',function(e){e.preventDefault();const q=new URLSearchParams();if($('#gsnFrom').val())q.set('from_date',$('#gsnFrom').val());if($('#gsnTo').val())q.set('to_date',$('#gsnTo').val());location.href=this.href+'?'+q.toString()});
 $(document).on('click','.js-show-gsn',function(){const id=$(this).data('id');$.get(@json(route('super.goods-sent-notes.show',['note'=>'__ID__'])).replace('__ID__',id)).done(note=>{const rows=(note.items||[]).map((line,i)=>{const p=line.production_order?.output_product||{};return `<tr><td>${i+1}</td><td>${esc(p.style_code)}</td><td>${esc(p.code)}</td><td>${esc(p.name)}</td><td>${esc(p.unit?.symbol||p.unit?.name)}</td><td class="text-end">${line.quantity}</td><td class="text-end">${line.cartons}</td><td>${esc(line.production_order?.number)}</td><td>${esc(line.production_order?.buyer_po_number)}</td><td>${esc(line.customer?.name)}</td></tr>`}).join('');$('#gsnDetailNo').text(note.number);$('#gsnDetailTable tbody').html(rows);$('#gsnDetailCard').removeClass('d-none');document.getElementById('gsnDetailCard').scrollIntoView({behavior:'smooth',block:'start'})}).fail(()=>Swal.fire({icon:'error',text:@json(__('ui.gsn.detail_failed'))}))});
 function esc(v){return $('<div>').text(v||'—').html()}
 $(document).on('click','.js-delete-gsn',function(){const id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),text:@json(__('ui.gsn.delete_help')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(r=>{if(r.isConfirmed)$.ajax({url:@json(route('super.goods-sent-notes.destroy',['note'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(x=>{table.ajax.reload(null,false);Swal.fire({icon:'success',text:x.message})}).fail(x=>Swal.fire({icon:'error',text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}))})});
});
</script>
@endpush
